 import unittest
from candidate import count_distinct_characters

class TestCountDistinctCharacters(unittest.TestCase):
    def test_normalcase(self):
        self.assertEqual(count_distinct_characters('xyzXYZ'), 3)

    def test_empty_string(self):
        self.assertEqual(count_distinct_characters(''), 0)

    def test_single_character_string(self):
        self.assertEqual(count_distinct_characters('a'), 1)

    def test_all_lowercase(self):
        self.assertEqual(count_distinct_characters('abcdefghijklmnopqrstuvwxyz'), 26)

    def test_all_uppercase(self):
        self.assertEqual(count_distinct_characters('ABCDEFGHIJKLMNOPQRSTUVWXYZ'), 26)

    def test_mixed_case(self):
        self.assertEqual(count_distinct_characters('abcABC123!@#'), 9)

    def test_whitespace(self):
        self.assertEqual(count_distinct_characters('abc ABC  123'), 9)

    def test_punctuation(self):
        self.assertEqual(count_distinct_characters('abc!@#$%^&*()_+-=[]{}|;':), 33)

    def test_numbers(self):
        self.assertEqual(count_distinct_characters('1234567890'), 10)

    def test_special_cases(self):
        self.assertEqual(count_distinct_characters(''), 0)
        self.assertEqual(count_distinct_characters(None), None)
        self.assertEqual(count_distinct_characters(123), TypeError)

if __name__ == '__main__':
    unittest.main()
